            &lt;/div&gt;
        &lt;/div&gt;&lt;figure class="kg-card kg-image-card kg-width-full"&gt;&lt;img src="__GHOST_URL__/content/images/2025/04/Pixelart-Comic-Cover-Apr-14-2025--4-.png" class="kg-image" alt="" loading="lazy" width="1536" height="1024" srcset="__GHOST_URL__/content/images/size/w600/2025/04/Pixelart-Comic-Cover-Apr-14-2025--4-.png 600w, __GHOST_URL__/content/images/size/w1000/2025/04/Pixelart-Comic-Cover-Apr-14-2025--4-.png 1000w, __GHOST_URL__/content/images/2025/04/Pixelart-Comic-Cover-Apr-14-2025--4-.png 1536w"&gt;&lt;/figure&gt;&lt;div class="kg-card kg-signup-card kg-width-wide " data-lexical-signup-form="" style="background-color: #F0F0F0; display: none;"&gt;

